module up_down_counter
    (
        input rst_n,
        input clk,
        input up_down,
        output reg [15:0] counter
    );

    reg [15:0] count;

    always @(posedge clk) 
    begin
        if (!rst_n)
            count <= 16'd0;
        else if (up_down)
            count <= count + 1;
        else
            count <= count - 1;
    end

    always @(posedge clk)
    begin
        counter <= count;
    end

endmodule

