module top_module(
  input ref_clk,
  input fb_clk,
  input reset,
  output out_clk,
  output locked
);parameter delay = 5; // fixed delay between reference clock and output clock

reg delayed_ref_clk;
reg [1:0] phase_detector_out;
reg [7:0] filter_out;
reg locked_reg;
wire phase_detector_in;

assign phase_detector_in = fb_clk & delayed_ref_clk;

always @(posedge ref_clk) begin
  delayed_ref_clk <= #delay ref_clk;
end

always @(posedge fb_clk or posedge delayed_ref_clk) begin
  phase_detector_out <= {phase_detector_out[0], phase_detector_in};
end

always @(posedge ref_clk) begin
  filter_out <= filter_out + phase_detector_out - filter_out[7];
end

always @(posedge ref_clk) begin
  if (reset) begin
    locked_reg <= 0;
  end else begin
    locked_reg <= (filter_out == 0);
  end
end

assign out_clk = delayed_ref_clk;

assign locked = locked_reg;

endmodule

module top_module(
    input [7:0] d_in,
    input [2:0] shift_amount,
    input clk,
    output [7:0] d_out
);reg [7:0] shifted_d_in;

    always @ (posedge clk) begin
        case (shift_amount)
            3'b000: shifted_d_in <= d_in;
            3'b001: shifted_d_in <= {d_in[6:0], 1'b0};
            3'b010: shifted_d_in <= {d_in[5:0], 2'b00};
            3'b011: shifted_d_in <= {d_in[4:0], 3'b000};
            3'b100: shifted_d_in <= {d_in[3:0], 4'b0000};
            3'b101: shifted_d_in <= {d_in[2:0], 5'b00000};
            3'b110: shifted_d_in <= {d_in[1:0], 6'b000000};
            3'b111: shifted_d_in <= {d_in[0], 7'b0000000};
        endcase
    end

    assign d_out = shifted_d_in;

endmodule

