  reg [7:0] count = 0; // number of elements in the FIFO

  wire [7:0] next_wr_ptr = wr_ptr + 1; // next write pointer
  wire [7:0] next_rd_ptr = rd_ptr + 1; // next read pointer
  wire [7:0] next_count = count + wr_en - rd_en; // next number of elements in the FIFO

  assign empty = (count == 0);
  assign full = (count == 256);

  always @(posedge wr_clk) begin
    if (wr_en && !full) begin
      fifo[wr_ptr] <= din;
      wr_ptr <= next_wr_ptr;
      count <= next_count;
    end
  end

  always @(posedge rd_clk) begin
    if (rd_en && !empty) begin
      dout <= fifo[rd_ptr];
      rd_ptr <= next_rd_ptr;
      count <= next_count;
    end
  end

  always @(posedge wr_clk or posedge rd_clk or posedge rst) begin
    if (rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
    end
  end

endmodule

module shift_register (CLK, RST, LOAD, IN, SI, OUT);
input CLK, RST, LOAD, SI;
input [7:0] IN;
output reg [7:0] OUT;

always @(posedge CLK or posedge RST) begin
	if (RST) begin
		OUT <= 8'b00000000;
	end
	else if (LOAD) begin
		OUT <= IN;
	end
	else begin
		OUT <= {OUT[6:0], SI};
	end
end

endmodule

