clk,
hex,
symbol
);input clk;
input [3:0] hex;

output [6:0] symbol;

reg [6:0] symbol;

always @(posedge clk)
case (hex)
4'h1 : symbol <= 7'b1001111;
4'h2 : symbol <= 7'b0010010;
4'h3 : symbol <= 7'b0000110;
4'h4 : symbol <= 7'b1001100;
4'h5 : symbol <= 7'b0100100;
