4'hC : symbol <= 7'b0110001;
4'hD : symbol <= 7'b1000010;
4'hE : symbol <= 7'b0110000;
4'hF : symbol <= 7'b0111000;
default: symbol <= 7'b0000001;
endcase
endmodule

