  reg signed [M-1:0] a_reg; 
  reg signed [N-1:0] b_reg; 
  always @(posedge clk or posedge rst) 
  begin 
  if (rst) begin 
  a_reg <= 0; 
  b_reg <= 0; 
  p <= 0; 
  end 
  else if (en) begin 
  a_reg <= a; 
  b_reg <= b; 
  p <= a_reg * b_reg; 
  end 
  end 
