module top_module(
  input [n-1:0] data_in,
  input rst, clk,
  output [n+k-1:0] crc_out,
  output error
);parameter n = 8; // number of bits in the data block
parameter k = 4; // number of bits in the CRC code

// specify the polynomial divisor as a binary number
parameter poly = 4'b1001; 

reg [k-1:0] crc_reg;
reg [n+k-1:0] crc_data;
wire [n+k-1:0] crc_xor;

assign crc_xor = crc_data ^ ({crc_reg, {k{1'b0}}});

always @(posedge clk or negedge rst) begin
  if (!rst) begin
    crc_reg <= {k{1'b0}};
    crc_data <= {data_in, {k{1'b0}}};
  end else begin
    crc_reg <= crc_xor[n+k-1:k];
    crc_data <= {crc_xor[n+k-2:0], {1'b0}};
  end
end

assign crc_out = crc_data;
assign error = (crc_reg != {k{1'b0}});

endmodule

