module binary_counter(
    input clk,
    input reset_n,
    input enable,
    output reg [8:0] count
);

    always @(posedge clk) begin
        if (!reset_n) begin
            // Synchronous reset: Reset the counter to 9'b000000000
            count <= 9'b000000000;
        end else if (enable) begin
            // Increment operation: Increment counter by 2 when enable is high
            count <= count + 2;
        end
    end

endmodule

