  input rd_rst_reg_reg;

  wire ram_empty_fb_i;
  wire ram_empty_i;

  assign out = ram_empty_fb_i;

  // Using D flip-flops instead of FDPE
  reg ram_empty_fb_i_reg;
  reg ram_empty_i_reg;

