      ram_empty_i_reg <= 1'b1; // async reset
    end else begin
      ram_empty_i_reg <= count_d1_reg[1];
    end
  end

  assign ram_empty_fb_i = ram_empty_fb_i_reg;
  assign ram_empty_i = ram_empty_i_reg;

endmodule

