module traffic_light_controller(
    input clk,
    input reset,
    output reg [2:0] lights_north_south,
    output reg [2:0] lights_east_west
);
    reg [2:0] state;
    reg [23:0] timer;

    parameter NS_GREEN = 3'b001, NS_YELLOW = 3'b010, NS_RED = 3'b100;
    parameter EW_GREEN = 3'b001, EW_YELLOW = 3'b010, EW_RED = 3'b100;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 3'd0;
            timer <= 24'd0;
            lights_north_south <= NS_GREEN;
            lights_east_west <= EW_RED;
        end else begin
            timer <= timer + 1;
            case (state)
                3'd0: if (timer == 24'd5000000) begin
                    state <= 3'd1;
                    timer <= 24'd0;
                    lights_north_south <= NS_YELLOW;
                    lights_east_west <= EW_RED;
                end
                3'd1: if (timer == 24'd1000000) begin
                    state <= 3'd2;
                    timer <= 24'd0;
                    lights_north_south <= NS_RED;
                    lights_east_west <= EW_GREEN;
                end
                3'd2: if (timer == 24'd5000000) begin
                    state <= 3'd3;
                    timer <= 24'd0;
                    lights_north_south <= NS_RED;
                    lights_east_west <= EW_YELLOW;
                end
                3'd3: if (timer == 24'd1000000) begin
                    state <= 3'd0;
                    timer <= 24'd0;
                    lights_north_south <= NS_GREEN;
                    lights_east_west <= EW_RED;
                end
            endcase
        end
    end
endmodule

