module fsm (
  input clk,
  input reset,
  input x,
  output reg z);parameter S0=0, S1=1, S2=2, S3=3;
	reg [1:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= S0;
		else state <= next;
	end

	always_comb begin
		case (state)
			S0: next = x ? S2 : S3;
			S1: next = x ? S0 : S2;
			S2: next = x ? S3 : S1;
			S3: next = x ? S1 : S0;
			default: next = 'x;
		endcase
	end

	assign z = (state == S2) || (state == S3);

endmodule

