module top_module (
        input clk,
        input areset,
        input brew_button,
        input brew_done,
        output reg brewing);parameter Idle=1'b0, Brewing=1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Idle;
		else begin
			case (state)
				Idle: state <= brew_button ? Brewing : Idle;
				Brewing: state <= brew_done ? Idle : Brewing;
			endcase
		end
	end

	assign brewing = (state == Brewing);

endmodule

module top_module(
    Q      ,
    RESET_B,
    D      ,
    GATE_N
);output reg Q;      // Declare Q as a reg since it will be assigned in procedural blocks
    input  RESET_B;
    input  D;
    input  GATE_N;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB;
    supply0 VNB;

    reg D_ff;

    // D flip-flop to store input value
    always @(posedge VPWR or negedge RESET_B) begin
        if (!RESET_B) begin
            D_ff <= 1'b0;
        end else begin
            D_ff <= D;
        end
    end

    // Output assignment based on gate and reset conditions
    always @* begin
        if (!RESET_B) begin
            Q = 1'b0;
        end else if (!GATE_N) begin
            Q = D_ff;
        end
    end

endmodule

module top_module(
  input [n-1:0] bin,
  input [n-1:0] gray,
  output [n-1:0] gray_out,
  output [n-1:0] bin_out
);parameter n = 4; // number of bits

assign gray_out = bin ^ (bin >> 1);
assign bin_out = gray ^ (gray >> 1);

endmodule

module top_module(
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output overflow
);wire [8:0] temp_sum;
wire carry;

assign temp_sum = {1'b0, a} + {1'b0, b}; // Add a and b, include a carry bit
assign sum = temp_sum[7:0]; // Output the sum
assign carry = temp_sum[8]; // Check if there was an overflow

assign overflow = (a[7] == b[7] && sum[7] != a[7]) || (a[7] != b[7] && sum[7] == carry);

endmodule

