always @(*) begin
    stage2_SUM[1] = A[1] ^ B[1] ^ stage1_COUT;
    stage2_COUT = (A[1] & B[1]) | (A[1] & stage1_COUT) | (B[1] & stage1_COUT);
end

// Stage 3
