    stage3_SUM[2] = A[2] ^ B[2] ^ stage2_COUT;
    COUT = (A[2] & B[2]) | (A[2] & stage2_COUT) | (B[2] & stage2_COUT);
end

// Stage 4
always @(*) begin
    stage3_SUM[3] = A[3] ^ B[3] ^ COUT;
    SUM = stage3_SUM;
end

endmodule

