module top_module(
  input wr_clk,
  input wr_en,
  input [31:0] wr_data,
  input rd_clk,
  input rd_en,
  output reg [31:0] rd_data,
  output reg empty,
  output reg full
);// Define FIFO parameters
  parameter WIDTH = 32;
  parameter DEPTH = 8192;
  parameter ADDR_WIDTH = $clog2(DEPTH);

  // Define RAM memory
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  // Define read and write pointers
  reg [ADDR_WIDTH-1:0] wr_ptr = 0;
  reg [ADDR_WIDTH-1:0] rd_ptr = 0;

  // Define full and empty flags
  wire [ADDR_WIDTH-1:0] next_wr_ptr = wr_ptr + 1;
  wire [ADDR_WIDTH-1:0] next_rd_ptr = rd_ptr + 1;

  // Remove the 'wire' definitions for full and empty and use the reg outputs
  always @* begin
    full = (next_wr_ptr == rd_ptr);
    empty = (wr_ptr == rd_ptr);
  end

  // Write logic
  always @(posedge wr_clk) begin
    if (wr_en && !full) begin
      mem[wr_ptr] <= wr_data;
      wr_ptr <= next_wr_ptr;
    end
  end

  // Read logic
  always @(posedge rd_clk) begin
    if (rd_en && !empty) begin
      rd_data <= mem[rd_ptr];
      rd_ptr <= next_rd_ptr;
    end
  end

endmodule

module top_module(
    input A1_N,
    input A2_N,
    input B1,
    input B2,
    output Y
