description:
Design a pulse generator circuit that produces a high output pulse for a configurable duration each time the input signal transitions to high, provided it is not already active. The width of the pulse is determined by the parameter PULSE_WIDTH, which defines how many clock cycles the pulse will remain high. The output pulse_signal is asserted for the specified duration, after which it automatically returns to low until the input signal goes high again.
module top_module(
  input clk,
  input input_signal,
  output reg pulse_signal
);

code:
module top_module(
  input clk,
  input input_signal,
  output reg pulse_signal
);reg [31:0] counter = 0;
  reg pulse_active = 0;
  parameter PULSE_WIDTH = 10; // configurable pulse width

  always @(posedge clk) begin
    if (input_signal && !pulse_active) begin
      pulse_active = 1;
      counter = 0;
    end
    else if (pulse_active) begin
      if (counter < PULSE_WIDTH) begin
        pulse_signal <= 1;
        counter <= counter + 1;
      end
      else begin
        pulse_signal <= 0;
        pulse_active <= 0;
      end
    end
    else begin
      pulse_signal <= 0;
    end
  end

endmodule

